//! 《周易》经文（卦辞、爻辞、用九用六）。由 scripts/folk/gen_zhouyi_text.py 自维基文库录文
//! （vendor/folk/wikisource/周易/，原样）生成，勿手改。卦以六位二进制表示，初爻为最低位、阳为 1。

/// (通行本卦序 1—64, 卦名, 卦画, 卦辞, 六爻辞（初至上）, 用九/用六)
pub const GUA: [(u8, &str, u8, &str, [&str; 6], Option<&str>); 64] = [
    (1, "乾", 0b111111, "元亨。利貞。", ["初九：潛龍勿用。", "九二：見龍在田，利見大人。", "九三：君子終日乾乾，夕惕若；厲，无咎。", "九四：或躍在淵，无咎。", "九五：飛龍在天，利見大人。", "上九：亢龍，有悔。"], Some("用九：見羣龍无首，吉。")),
    (2, "坤", 0b000000, "元亨。利牝馬之貞。", ["初六：履霜，堅冰至。", "六二：直方大，不習无不利。", "六三：含章，可貞。或從王事，无成有終。", "六四：括囊，无咎无譽。", "六五：黃裳，元吉。", "上六：龍戰于野，其血玄黃。"], Some("用六：利永貞。")),
    (3, "屯", 0b010001, "元亨，利貞。勿用有攸往，利建侯。", ["初九：{{另|磐|盤}}桓，利居貞，利建侯。", "六二：屯如邅如，乘馬班如，匪寇婚媾，女子貞不字，十年乃字。", "六三：即鹿无虞，惟入于林中，君子幾不如舍，往吝。", "六四：乘馬班如，求婚媾，往，吉无不利。", "九五：屯其膏；小貞吉，大貞凶。", "上六：乘馬班如，泣血漣如。"], None),
    (4, "蒙", 0b100010, "亨。匪我求童蒙，童蒙求我。初筮告，再三瀆，瀆則不告。利貞。", ["初六：發蒙，利用刑人，用說桎梏，以往吝。", "九二：包蒙吉，納婦吉，子克家。", "六三：勿用{{另|取|娶}}女，見金夫，不有躬，无攸利。", "六四：困蒙，吝。", "六五：童蒙，吉。", "上九：擊蒙，不利為寇，利禦寇。"], None),
    (5, "需", 0b010111, "有孚，光亨。貞吉，利涉大川。", ["初九：需于郊，利用恆，无咎。", "九二：需于沙，小有言，終吉。", "九三：需于泥，致寇至。", "六四：需于血，出自穴。", "九五：需于酒食，貞吉。", "上六：入于穴，有不速之客三人來，敬之終吉。"], None),
    (6, "訟", 0b111010, "有孚，窒，惕，中吉，終凶。利見大人，不利涉大川。", ["初六：不永所事，小有言，終吉。", "九二：不克訟，歸而逋，其邑人三百戶无眚。", "六三：食舊德，貞厲，終吉。或從王事，无成。", "九四：不克訟，復即命渝，安貞吉。", "九五：訟，元吉。", "上九：或錫之鞶帶，終朝三{{另|褫|拕}}之。"], None),
    (7, "師", 0b000010, "貞丈人吉，无咎。", ["初六：師出以律，否臧，凶。", "九二：在師中吉，无咎；王三錫命。", "六三：師或輿尸，凶。", "六四：師左次，无咎。", "六五：田有禽，利執言，无咎。長子帥師，弟子輿尸，貞凶。", "上六：大君有命，開國承家，小人勿用。"], None),
    (8, "比", 0b010000, "吉。原筮元永貞，无咎。不寧方來，後夫凶。", ["初六：有孚，比之，无咎。有孚盈缶，終來有它，吉。", "六二：比之自內，貞吉。", "六三：比之匪人。", "六四：外比之，貞吉。", "九五：顯比。王用三{{另|敺|驅}}，失前禽，邑人不誡，吉。", "上六：比之无首，凶。"], None),
    (9, "小畜", 0b110111, "亨。密雲不雨，自我西郊。", ["初九：復自道，何其咎，吉。", "九二：牽復，吉。", "九三：{{另|車|輿}}說{{另|輹|輻}}，夫妻反目。", "六四：有孚，血去惕出，无咎。", "九五：有孚攣如，富以其鄰。", "上九：既雨既處，尚{{另|得|德}}載，婦貞厲，月幾望，君子征凶。"], None),
    (10, "履", 0b111011, "履虎尾，不咥人，亨。", ["初九：素履，往无咎。", "九二：履道坦坦，幽人貞吉。", "六三：眇能視，跛能履，履虎尾，咥人，凶。武人為于大君。", "九四：履虎尾，愬愬終吉。", "九五：夬履，貞厲。", "上九：視履考詳，其旋元吉。"], None),
    (11, "泰", 0b000111, "小往大來，吉亨。", ["初九：拔茅茹以其彙，征吉。", "九二：包荒。用馮河，不遐遺；朋亡。得尚于中行。", "九三：无平不陂，无往不復，艱貞无咎。勿恤其孚，于食有福。", "六四：翩翩，不富以其鄰；不戒以孚。", "六五：帝乙歸妹，以祉，元吉。", "上六：城復于隍，勿用師，自邑告命，貞吝。"], None),
    (12, "否", 0b111000, "否之匪人，不利君子貞，大往小來。", ["初六，拔茅茹以其彙，貞吉。亨。", "六二，包承，小人吉，大人否。亨。", "六三，包羞。", "九四，有命，无咎，疇離祉。", "九五，休否，大人吉。其亡其亡，繫于{{另|包|苞}}桑。", "上九，傾否，先否後喜。"], None),
    (13, "同人", 0b111101, "同人于野，亨。 利涉大川，利君子貞。", ["初九：同人于門，無咎。", "六二：同人于宗，吝。", "九三：伏戎于莽，升其高陵，三歲不興。", "九四：乘其{{另|庸|墉}}，弗克攻，吉。", "九五：同人，先號啕而後笑。大師克相遇。", "上九：同人于郊，無悔。"], None),
    (14, "大有", 0b101111, "元亨。", ["初九：无交害，匪咎，艱則无咎。", "九二：大{{另|轝|車}}以載，有攸往，无咎。", "九三：公用亨于天子，小人弗克。", "九四：匪其{{另|尫|彭}}，无咎。", "六五：厥孚交如，威如；吉。", "上九：自天{{另|佑|右}}之，吉无不利。"], None),
    (15, "謙", 0b000100, "亨，君子有終。", ["初六：謙謙君子，用涉大川，吉。", "六二：鳴謙，貞吉。", "九三：勞謙君子，有終吉。", "六四：无不利，撝謙。", "六五：不富，以其鄰，利用侵伐，无不利。", "上六：鳴謙，利用行師，征邑國。"], None),
    (16, "豫", 0b001000, "利建侯行師。", ["初六：鳴豫，凶。", "六二：介于石，不終日，貞吉。", "六三：盱豫，悔。遲有悔。", "九四：由豫，大有得。勿疑。朋盍{{另|戠|簪}}。", "六五：貞疾，恆不死。", "上六：冥豫，成有渝，无咎。"], None),
    (17, "隨", 0b011001, "元亨。利貞。无咎。", ["初九：官有渝，貞吉。出門交有功。", "六二：係小子，失丈夫。", "六三：係丈夫，失小子。隨，有求得利，居貞。", "九四：隨有獲，貞凶。有孚在道，以明，何咎。", "九五：孚于嘉，吉。", "上六：拘係之，乃從維之。王用亨于西山。"], None),
    (18, "蠱", 0b100110, "元亨。利涉大川。先甲三日，後甲三日。", ["初六：幹父之蠱，有子考，无咎，厲終吉。", "九二：幹母之蠱，不可貞。", "九三：幹父之蠱，小有悔，无大咎。", "六四：裕父之蠱，往見吝。", "六五：幹父之蠱，用譽。", "上九：不事王侯，高尚其事。"], None),
    (19, "臨", 0b000011, "元亨。利貞。至于八月有凶。", ["初九：咸臨，貞吉。", "九二：咸臨，吉无不利。", "六三：甘臨，无攸利。既憂之，无咎。", "六四：至臨，无咎。", "六五：知臨，大君之宜，吉。", "上六：敦臨，吉无咎。"], None),
    (20, "觀", 0b110000, "盥而不薦，有孚顒若。", ["初六：童觀，小人无咎，君子吝。", "六二：窺觀，利女貞。", "六三：觀我生，進退。", "六四：觀國之光，利用賓于王。", "九五：觀我生，君子无咎。", "上九：觀其生，君子无咎。"], None),
    (21, "噬嗑", 0b101001, "亨。利用獄。", ["初九：屨校滅趾，无咎。", "六二：噬膚滅鼻，无咎。", "六三：噬{{另|昔|臘}}肉，遇毒；小吝，无咎。", "九四：噬乾胏，得金矢，利艱貞，吉。", "六五：噬乾肉，得黃金，貞厲，无咎。", "上九：何校滅耳，凶。"], None),
    (22, "賁", 0b100101, "亨。小利有攸往。", ["初九：賁其趾，舍車而徒。", "六二：賁其須。", "九三：賁如濡如，永貞吉。", "六四：賁如皤如，白馬翰如，匪寇婚媾。", "六五：賁於丘園，束帛戔戔，吝，終吉。", "上九：白賁，无咎。"], None),
    (23, "剝", 0b100000, "不利。有攸往。", ["初六：剝牀以足，蔑貞凶。", "六二：剝牀以辨，蔑貞凶。", "六三：剝之，无咎。", "六四：剝牀以膚，凶。", "六五：貫魚，以宮人寵，无不利。", "上九：碩果不食，君子{{另|德車|得輿}}，小人剝廬。"], None),
    (24, "復", 0b000001, "亨。出入无疾，朋來无咎。反復其道，七日來復，利有攸往。", ["初九：不遠復，无祇悔，元吉。", "六二：休復，吉。", "六三：頻復，厲无咎。", "六四：中行獨復。", "六五：敦復，无悔。", "上六：迷復，凶，有災眚。用行師，終有大敗，以其國君，凶；至于十年，不克征。"], None),
    (25, "无妄", 0b111001, "元亨。利貞。其匪正有眚，不利有攸往。", ["初九：无妄，往吉。", "六二：不耕穫，不菑畬，則利有攸往。", "六三：无妄之災，或繫之牛，行人之得，邑人之災。", "九四：可貞，无咎。", "九五：无妄之疾，勿藥有喜。", "上九：无妄，行有眚，无攸利。"], None),
    (26, "大畜", 0b100111, "利貞，不家食吉，利涉大川。", ["初九：有厲利已。", "九二：輿說{{另|輹|腹}}。", "九三：良馬逐，利艱貞，吉。日閑輿衛，利有攸往。", "六四：童牛之{{另|告|牿}}，元吉。", "六五：豶豕之牙，吉。", "上九：何天之衢，亨。"], None),
    (27, "頤", 0b100001, "貞吉。觀頤，自求口實。", ["初九：舍爾靈龜，觀我朵頤，凶。", "六二：顛頤，拂經，于丘頤，征凶。", "六三：拂頤，貞凶，十年勿用，无攸利。", "六四：顛頤吉，虎視眈眈，其欲逐逐，无咎。", "六五：拂經，居貞吉，不可涉大川。", "上九：由頤，厲吉，利涉大川。"], None),
    (28, "大過", 0b011110, "棟橈，利有攸往，亨。", ["初六：藉用白茅，无咎。", "九二：枯楊生稊，老夫得其女妻，无不利。", "九三：棟橈，凶。", "九四：棟隆，吉。有它吝。", "九五：枯楊生華，老婦得其士夫，无咎无譽。", "上六：過涉滅頂，凶，无咎。"], None),
    (29, "坎", 0b010010, "習坎：有孚，維心亨。行有尚。", ["初六：習坎，入于坎窞，凶。", "九二：坎有險，求小得。", "六三：來之坎坎，險且枕，入于坎窞，勿用。", "六四：{{另|尊酒簋，貳用缶。内約自牖|樽酒簋貳，用缶，納約自牖}}，終无咎。", "九五：坎不盈，{{另|禔|祗}}既平，无咎。", "上六：係用徽纆，寘于叢棘，三歲不得，凶。"], None),
    (30, "離", 0b101101, "利貞。亨。畜牝牛，吉。", ["初九：履錯然，敬之无咎。", "六二：黃離，元吉。", "九三：日昃之離，不鼓缶而歌，則大耋之{{另|差|嗟}}，凶。", "九四：突如其來如，焚如，死如，棄如。", "六五：出涕沱若，戚嗟若，吉。", "上九：王用出征，有嘉折首，獲匪其醜，无咎。"], None),
    (31, "咸", 0b011100, "亨。利貞。取女吉。", ["初六：咸其{{另|拇|母}}。", "六二：咸其腓，凶，居吉。", "九三：咸其股，執其隨，往吝。", "九四：貞吉悔亡，憧憧往來，朋從爾思。", "九五：咸其脢，无悔。", "上六：咸其輔，頰，舌。"], None),
    (32, "恒", 0b001110, "恆：亨，无咎。利貞，利有攸往。", ["初六：浚恆，貞凶，无攸利。", "九二：悔亡。", "九三：不恆其德，或承之羞，貞吝。", "九四：田无禽。", "六五：恆其德，貞，婦人吉，夫子凶。", "上六：{{另|震|振}}恆，凶。"], None),
    (33, "遯", 0b111100, "亨。小利貞。", ["初六：遯尾，厲，勿用有攸往。", "六二：執之用黃牛之革，莫之勝說。", "九三：係遯，有疾厲，畜臣妾吉。", "九四：好遯君子吉，小人否。", "九五：嘉遯，貞吉。", "上九：肥遯，无不利。"], None),
    (34, "大壯", 0b001111, "利貞。", ["初九：壯于趾，征凶，有孚。", "九二：貞吉。", "九三：小人用壯，君子用罔，貞厲。羝羊觸藩，羸其角。", "九四：貞吉悔亡，藩決不羸，壯于大{{另|轝|輿}}之{{另|腹|輹}}。", "六五：喪羊于易，无悔。", "上六：羝羊觸藩，不能退，不能遂，无攸利，艱則吉。"], None),
    (35, "晉", 0b101000, "康侯用錫馬蕃庶，晝日三接。", ["初六：晉如，摧如，貞吉。罔孚，裕无咎。", "六二：晉如，愁如，貞吉。受茲介福，于其王母。", "六三：眾允，悔亡。", "九四：晉如{{另|鼫|碩}}鼠，貞厲。", "六五：悔亡，{{另|矢|失}}得勿恤，往吉无不利。", "上九：晉其角，維用伐邑，厲吉无咎，貞吝。"], None),
    (36, "明夷", 0b000101, "利艱貞。", ["初九：明夷于飛，垂其翼。君子于行，三日不食，有攸往，主人有言。", "六二：明夷，夷于左股，用拯馬壯，吉。", "九三：明夷于南狩，得其大首，不可疾貞。", "六四：入于左腹，獲明夷之心，于出門庭。", "六五：箕子之明夷，利貞。", "上六：不明晦，初登于天，後入于地。"], None),
    (37, "家人", 0b110101, "利女貞。", ["初九：閑有家，悔亡。", "六二：无攸遂，在中饋，貞吉。", "九三：家人嗃嗃，悔厲吉；婦子嘻嘻，終吝。", "六四：富家，大吉。", "九五：王假有家，勿恤。吉。", "上九：有孚威如，終吉。"], None),
    (38, "睽", 0b101011, "小事吉。", ["初九：悔亡，喪馬勿逐，自復；見惡人无咎。", "九二：遇主于巷，无咎。", "六三：見輿曳，其牛{{另|𧤊|掣}}，其人天且劓，无初有終。", "九四：睽孤，遇元夫，交孚，厲无咎。", "六五：悔亡，厥宗噬膚，往何咎。", "上九：睽孤， 見豕負涂，載鬼一車， 先張之弧，後說之弧，匪寇婚媾，往遇雨則吉。"], None),
    (39, "蹇", 0b010100, "利西南，不利東北；利見大人，貞吉。", ["初六：往蹇，來譽。", "六二：王臣蹇蹇，匪躬之故。", "九三：往蹇來反。", "六四：往蹇來連。", "九五：大蹇朋來。", "上六：往蹇來碩，吉；利見大人。"], None),
    (40, "解", 0b001010, "利西南，无所往，其來復吉。有攸往，夙吉。", ["初六：无咎。", "九二：田獲三狐，得黃矢，貞吉。", "六三：負且乘，致寇至，貞吝。", "九四：解而拇，朋至斯孚。", "六五：君子{{另|惟|維}}有解，吉；有孚于小人。", "上六：公用射隼，于高{{另|墉|庸}}之上，獲之，无不利。"], None),
    (41, "損", 0b100011, "有孚，元吉。无咎，可貞，利有攸往。曷之用？二簋可用享。", ["初九：{{另|祀|已}}事遄往，无咎，酌損之。", "九二：利貞，征凶，弗損益之。", "六三：三人行，則損一人；一人行，則得其友。", "六四：損其疾，使遄有喜，无咎。", "六五：或益之，十朋之龜弗克違，元吉。", "上九：弗損益之，无咎，貞吉，利有攸往，得臣无家。"], None),
    (42, "益", 0b110001, "利有攸往。利涉大川。", ["初九：利用為大作，元吉，无咎。", "六二：或益之，十朋之龜弗克違，永貞吉。王用享于帝，吉。", "六三：益之用凶事，无咎。有孚中行，告公用圭。", "六四：中行，告公從。利用為依遷{{另|國|邦}}。", "九五：有孚惠心，勿問元吉。有孚惠我德。", "上九：莫益之，或擊之，立心勿恆，凶。"], None),
    (43, "夬", 0b011111, "揚于王庭，孚號，有厲，告自邑，不利即戎，利有攸往。", ["初九：壯于前趾，往不勝為咎。", "九二：惕號，莫夜有戎，勿恤。", "九三：壯于頄，有凶。君子夬夬，獨行遇雨，若濡有慍，无咎。", "九四：臀无膚，其行次且。牽羊悔亡，聞言不信。", "九五：莧陸夬夬，中行无咎。", "上六：无號，終有凶。"], None),
    (44, "姤", 0b111110, "女壯，勿用取女。", ["初六：系于金柅，貞吉，有攸往，見凶，羸豕，孚，{{另|蹢躅|𨅙𨄃}}。", "九二：包有魚，无咎，不利賓。", "九三：臀无膚，其行次且，厲，无大咎。", "九四：包无魚，起凶。", "九五：以杞{{另|包|苞}}瓜，含章，有隕自天。", "上九：姤其角，吝，无咎。"], None),
    (45, "萃", 0b011000, "王假有廟，利見大人，亨。利貞。用大牲吉，利有攸往。", ["初六：有孚不終，乃亂乃萃，若號一握為笑，勿恤，往无咎。", "六二：引吉，无咎，孚乃利用禴。", "六三：萃如，嗟如，无攸利，往无咎，小吝。", "九四：大吉，无咎。", "九五：萃有位，无咎。匪孚，元永貞，悔亡。", "上六：齎{{另|資|咨}}涕洟，无咎。"], None),
    (46, "升", 0b000110, "元亨，用見大人，勿恤，南征吉。", ["初六：允升，大吉。", "九二：孚乃利用禴，无咎。", "九三：升虛邑。", "六四：王用{{另|享|亨}}于岐山，吉无咎。", "六五：貞吉，升階。", "上六：冥升，利于不息之貞。"], None),
    (47, "困", 0b011010, "亨，貞大人吉，无咎，有言不信。", ["初六：臀困于株木，入于幽谷，三歲不覿。", "九二：困于酒食，朱紱方來，利用亨祀，征凶，无咎。", "六三：困于石，據于蒺{{另|蔾|藜}}，入于其宮，不見其妻，凶。", "九四：來{{另|荼荼|徐徐}}，困于金{{另|轝|車}}，吝，有終。", "九五：劓刖，困于赤紱，乃徐有說，利用祭祀。", "上六：困于葛藟，于臲卼，曰動悔。有悔，征吉。"], None),
    (48, "井", 0b010110, "改邑不改井，无喪无得，往來井井。汔至亦未繘井。羸其瓶，凶。", ["初六：井泥不食，舊井无禽。", "九二：井谷射鮒，瓮敝漏。", "九三：井渫不食，為我心惻，可用汲，王明，並受其福。", "六四：井甃，无咎。", "九五：井冽，寒泉食。", "上六：井收勿幕，有孚元吉。"], None),
    (49, "革", 0b011101, "已日乃孚，元亨。利貞。悔亡。", ["初九：鞏用黃牛之革。", "六二：已日乃革之，征吉，无咎。", "九三：征凶，貞厲，革言三就，有孚。", "九四：悔亡，有孚改命，吉。", "九五：大人虎變，未占有孚。", "上六：君子豹變，小人革面，征凶，居貞吉。"], None),
    (50, "鼎", 0b101110, "元吉，亨。", ["初六：鼎顛趾，利出否，得妾以其子，无咎。", "九二：鼎有實，我仇有疾，不我能即，吉。", "九三：鼎耳革，其行塞，雉膏不食，方雨虧悔，終吉。", "九四：鼎折足，覆公餗，其{{另|刑|形}}渥，凶。", "六五：鼎黃耳金鉉，利貞。", "上九：鼎玉鉉，大吉，无不利。"], None),
    (51, "震", 0b001001, "亨。震來虩虩，笑言啞啞。震驚百里，不喪匕鬯。", ["初九：震來虩虩，後笑言啞啞，吉。", "六二：震來厲，億喪貝，躋于九陵，勿逐，七日得。", "六三：震蘇蘇，震行无眚。", "九四：震遂泥。", "六五：震往來厲，億无喪，有事。", "上六：震索索，視矍矍，征凶。震不于其躬，于其鄰，无咎。婚媾有言。"], None),
    (52, "艮", 0b100100, "艮其背，不獲其身，行其庭，不見其人，无咎。", ["初六：艮其趾，无咎，利永貞。", "六二：艮其腓，不拯其隨，其心不快。", "九三：艮其限，{{另|裂|列}}其夤，厲{{另|閽|薰}}心。", "六四：艮其身，无咎。", "六五：艮其輔，言有{{另|孚|序}}，悔亡。", "上九：敦艮，吉。"], None),
    (53, "漸", 0b110100, "女歸吉，利貞。", ["初六：鴻漸于干，小子厲，有言，无咎。", "六二：鴻漸于磐，飲食衎衎，吉。", "九三：鴻漸于陸，夫征不復，婦孕不育，凶；利禦寇。", "六四：鴻漸于木，或得其桷，无咎。", "九五：鴻漸于陵，婦三歲不孕，終莫之勝，吉。", "上九：鴻漸于陸，其羽可用為儀，吉。"], None),
    (54, "歸妹", 0b001011, "征凶，无攸利。", ["初九：歸妹以娣，跛能履，征吉。", "九二：眇{{另|能|而}}視，利幽人之貞。", "六三：歸妹以須，反歸以娣。", "九四：歸妹愆期，遲歸有時。", "六五：帝乙歸妹，其君之袂，不如其娣之袂良，月幾望，吉。", "上六：女承筐无實，士刲羊无血，无攸利。"], None),
    (55, "豐", 0b001101, "亨。王假之，勿憂，宜日中。", ["初九：遇其配主，雖旬无咎，往有尚。", "六二：豐其蔀，日中見斗，往得疑疾，有孚發若，吉。", "九三：豐其沛，日中見沬，折其右肱，无咎。", "九四：豐其蔀，日中見斗，遇其夷主，吉。", "六五：來章，有慶譽，吉。", "上六：豐其屋，蔀其家，窺其戶，闃其无人，三歲不觌，凶。"], None),
    (56, "旅", 0b101100, "小亨，旅貞吉。", ["初六：旅瑣瑣，斯其所取災。", "六二：旅即次，懷其資，得{{另|僮|童}}僕貞。", "九三：旅焚其次，喪其{{另|僮|童}}僕，貞厲。", "九四：旅于處，得其資斧，我心不快。", "六五：射雉一矢亡，終以譽命。", "上九：鳥焚其巢，旅人先笑後號咷。喪牛于易，凶。"], None),
    (57, "巽", 0b110110, "小亨。利有攸往。利見大人。", ["初六：進退，利武人之貞。", "九二：巽在牀下，用史巫紛若，吉无咎。", "九三：頻巽，吝。", "六四：悔亡，田獲三品。", "九五：貞吉悔亡，无不利。无初有終，先庚三日，後庚三日，吉。", "上九：巽在牀下，喪其資斧，貞凶。"], None),
    (58, "兌", 0b011011, "亨。利貞。", ["初九：和兌，吉。", "九二：孚兌，吉，悔亡。", "六三：來兌，凶。", "九四：商兌，未寧，介疾有喜。", "九五：孚于剝，有厲。", "上六：引兌。"], None),
    (59, "渙", 0b110010, "亨，王假有廟，利涉大川，利貞。", ["初六：用拯馬壯，吉，悔亡。", "九二：渙奔其机，悔亡。", "六三：渙其躬，无悔。", "六四：渙其群，元吉。渙有丘，匪夷所思。", "九五：渙汗其大號，渙王居，无咎。", "上九：渙其血，去逖出，无咎。"], None),
    (60, "節", 0b010011, "亨。苦節不可貞。", ["初九：不出戶庭，无咎。", "九二：不出門庭，凶。", "六三：不節若，則嗟若，无咎。", "六四：安節，亨。", "九五：甘節，吉；往有尚。", "上六：苦節，貞凶，悔亡。"], None),
    (61, "中孚", 0b110011, "豚魚吉，利涉大川，利貞。", ["初九：虞吉，有{{另|它|他}}不燕。", "九二：鳴鶴在陰，其子和之，我有好爵，吾與爾靡之。", "六三：得敵，或鼓或罷，或泣或歌。", "六四：月{{另|既|几、幾}}望，馬匹亡，无咎。", "九五：有孚攣如，无咎。", "上九：翰音登于天，貞凶。"], None),
    (62, "小過", 0b001100, "亨。利貞。可小事，不可大事。飛鳥遺之音，不宜上宜下，大吉。", ["初六：飛鳥以凶。", "六二：過其祖，遇其妣；不及其君，遇其臣；无咎。", "九三：弗過防之，從或戕之，凶。", "九四：无咎，弗過遇之。往厲必戒，勿用永貞。", "六五：密雲不雨，自我西郊，公弋取彼在穴。", "上六：弗遇過之，飛鳥離之，凶，是謂災眚。"], None),
    (63, "既濟", 0b010101, "亨小。利貞。初吉終亂。", ["初九：曳其輪，濡其尾，无咎。", "六二：婦喪其茀，勿逐，七日得。", "九三：高宗伐鬼方，三年克之，小人勿用。", "六四：繻有衣袽，終日戒。", "九五：東鄰殺牛，不如西鄰之禴祭，實受其福。", "上六：濡其首，厲。"], None),
    (64, "未濟", 0b101010, "亨。小狐汔濟，濡其尾，无攸利。", ["初六：濡其尾，吝。", "九二：曳其輪，貞吉。", "六三：未濟，征凶，利涉大川。", "九四：貞吉，悔亡，震用伐鬼方，三年有賞于大{{另|國|邦}}。", "六五：貞吉，无悔，君子之光，有孚，吉。", "上九：有孚于飲酒，无咎，濡其首，有孚失是。"], None),
];
